// Desired label NAMES from AI
const wantedNames = [
  $node["B-Label Gate"].json.a_label,
  $node["B-Label Gate"].json.b_label
].filter(l => l && l !== "null");

// Grab email metadata to carry through (fixes paired item chain break)
const gmailData = $node["Gmail Trigger"].json;
const fromRaw = gmailData.From || '';
const emailMatch = fromRaw.match(/<([^>]+)>/);
const senderEmail = emailMatch ? emailMatch[1].toLowerCase() : fromRaw.toLowerCase().trim();

const items = $input.all().map(i => i.json);
const nameToId = new Map(items.map(l => [l.name, l.id]));

const wantedIds = wantedNames.map(n => nameToId.get(n)).filter(Boolean);

if (wantedIds.length !== wantedNames.length) {
  const missing = wantedNames.filter(n => !nameToId.get(n));
  throw new Error("Missing Gmail labels: " + missing.join(", "));
}

return [{
  json: {
    messageId: gmailData.id,
    threadId: gmailData.threadId,
    senderEmail: senderEmail,
    senderName: fromRaw,
    subject: gmailData.Subject || '',
    snippet: gmailData.snippet || '',
    a_label: $node["B-Label Gate"].json.a_label || '',
    b_label: $node["B-Label Gate"].json.b_label || null,
    a_confidence: $node["B-Label Gate"].json.a_confidence || 0,
    b_confidence: $node["B-Label Gate"].json.b_confidence || 0,
    labelIds: wantedIds,
    wantedNames
  }
}];

const { messageId, threadId, senderEmail, senderName, subject, snippet, labelIds, a_label, b_label, a_confidence, b_confidence } = $json;

if (!messageId) throw new Error("Missing messageId");
if (!Array.isArray(labelIds) || labelIds.length === 0) throw new Error("Missing labelIds");

return labelIds.map(labelId => ({
  json: { messageId, threadId, senderEmail, senderName, subject, snippet, labelId, a_label, b_label, a_confidence, b_confidence }
}));

const raw = $json.triage?.skip ?? $json.skip ?? false;

const skip_bool =
  raw === true ? true :
  raw === false ? false :
  (typeof raw === "string" ? raw.trim().toLowerCase() === "true" : false);

return [{ json: { ...$json, skip_bool } }];

// Keep the original Gmail trigger item + add parsed AI fields onto it

const aiText = $json.output?.[0]?.content?.[0]?.text;
if (!aiText) throw new Error("No OpenAI text output found at output[0].content[0].text");

let parsed;
try {
  parsed = JSON.parse(aiText);
} catch (e) {
  throw new Error("OpenAI output was not valid JSON. Raw text: " + aiText);
}

// IMPORTANT: merge the parsed AI fields into the incoming item
// so we keep the Gmail fields like id, labels, Subject, From, etc.
return [{
  ...$json,          // original item (from OpenAI node input)
  triage: parsed,    // put AI result under triage (clean namespace)
  ...parsed          // ALSO flatten for convenience (optional)
}];

// ===== SETTINGS =====
const B_LABEL_MIN_CONFIDENCE = 0.80; // B-label confidence threshold

// ===== INPUT =====
const a = $json.a_label ?? $json.triage?.a_label ?? null;
let b = $json.b_label ?? $json.triage?.b_label ?? null;

const aConf = $json.a_confidence ?? $json.triage?.a_confidence ?? 0;
const bConf = $json.b_confidence ?? $json.triage?.b_confidence ?? 0;

// Normalize b_label strings like "null"
if (b === "null") b = null;

// B-label only allowed for Sales/CS
const bAllowed = (a === "TAG-SYS/Sales" || a === "TAG-SYS/CS");

// Gate rule: must pass BOTH a_confidence >= 0.70 AND b_confidence >= 0.80
if (!bAllowed || aConf < 0.70 || bConf < B_LABEL_MIN_CONFIDENCE || !b) {
  b = null;
}

// Extra safety: prefix match
if (b && a === "TAG-SYS/Sales" && !String(b).startsWith("TAG-SYS/Sales/")) b = null;
if (b && a === "TAG-SYS/CS" && !String(b).startsWith("TAG-SYS/CS/")) b = null;

// Write back
const out = { 
  ...$json, 
  a_confidence: aConf,
  b_confidence: bConf,
  b_label: b 
};

if (out.triage && typeof out.triage === "object") {
  out.triage = { 
    ...out.triage, 
    a_confidence: aConf,
    b_confidence: bConf,
    b_label: b 
  };
}

return [{ json: out }];

